import urllib.request
import json

def fetch_json(url):
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=10) as r:
            return json.loads(r.read())
    except:
        return None

# Fetch all ETF data with volume
etfs = ['SPYM', 'SCHG', 'DYNF', 'CGGR', 'SPHQ', 'XLG', 'AIQ', 'SOXQ', 'PSI']
results = {}
for etf in etfs:
    d = fetch_json(f"https://query2.finance.yahoo.com/v8/finance/chart/{etf}?interval=1d&range=5d")
    if d:
        try:
            result = d['chart']['result'][0]
            meta = result['meta']
            price = meta.get('regularMarketPrice') or meta.get('chartPreviousClose')
            # Get volume from info endpoint
            info_d = fetch_json(f"https://query1.finance.yahoo.com/v10/finance/quoteSummary/{etf}?modules=summaryDetail")
            vol = 0
            if info_d and 'quoteSummary' in info_d:
                try:
                    vol = info_d['quoteSummary']['result'][0]['summaryDetail']['averageVolume']['raw'] or 0
                except:
                    pass
            timestamps = result['timestamp']
            closes = result['indicators']['quote'][0]['close']
            valid = [(t, c) for t, c in zip(timestamps, closes) if c is not None]
            if len(valid) >= 2:
                today = valid[-1][1]
                yesterday = valid[-2][1]
                chg = (today - yesterday) / yesterday * 100
                results[etf] = {'price': today, 'chg': chg, 'vol': vol}
            elif len(valid) == 1:
                results[etf] = {'price': valid[0][1], 'chg': 0, 'vol': vol}
        except Exception as e:
            results[etf] = {'error': str(e)}

print("ETF Prices & Volume:")
for etf, d in results.items():
    if 'error' not in d:
        vol_str = f"{d['vol']/1e6:.1f}M" if d['vol'] else "N/A"
        print(f"{etf}: ${d['price']:.2f} ({d['chg']:+.2f}%) | Vol: {vol_str}")
    else:
        print(f"{etf}: ERROR - {d['error']}")
